	@ParameterizedTest
	@ValueSource(ints = { 64, 512 })
	void repeatedVariablesWeightEligibleFractionsInsideEachPatternPopulation(int budget, @TempDir Path directory)
			throws Exception {
		int rowsPerPlane = 256;
		try (Fixture fixture = Fixture.openSeeded(directory, budget, 20_000L, "posc", connection -> {
			for (int row = 0; row < rowsPerPlane; row++) {
				IRI explicit = VF.createIRI("urn:qualified-sampling:aaa:" + row);
				IRI inferred = VF.createIRI("urn:qualified-sampling:zzz:" + row);
				IRI other = VF.createIRI("urn:qualified-sampling:other");
				connection.addStatement(explicit, PREDICATE, row % 2 == 0 ? explicit : other);
				connection.addInferredStatement(inferred, PREDICATE, inferred);
			}
		}); ReadSession read = fixture.openRead()) {
			TripleStore triples = fixture.store.getBackingStore().getTripleStore();
			long predicate = fixture.values().getStatementId(read.values, PREDICATE);
			TripleStore.PreparedIndexCount explicit = triples.prepareExactIndexCount(read.txn, -1L, predicate,
					-1L, -1L, true);
			TripleStore.PreparedIndexCount inferred = triples.prepareExactIndexCount(read.txn, -1L, predicate,
					-1L, -1L, false);
			assertNotNull(explicit);
			assertNotNull(inferred);
			assertTrue(explicit.highPageReads() + inferred.highPageReads() <= budget);
			assertEquals(rowsPerPlane, explicit.execute().orElseThrow());
			assertEquals(rowsPerPlane, inferred.execute().orElseThrow());

			StatementPattern pattern = new StatementPattern(Var.of("value"), Var.of("predicate", PREDICATE),
					Var.of("value"));
			Filter filter = new Filter(pattern, new Compare(new Str(Var.of("value")),
					new ValueConstant(VF.createLiteral("urn:qualified-sampling:m")), Compare.CompareOp.LT));
			PlanningGraphDomains.capture(filter, PlanningGraphDomain.defaultGraph());
			PatternFilterSampleEstimate estimate = fixture.sample(read, filter);
			long[] matched = new long[2];
			long[] eligible = new long[2];
			for (PlaneRow row : fixture.trace.observed) {
				int plane = row.explicit() ? 0 : 1;
				matched[plane]++;
				if (row.quad()[TripleIndex.SUBJ_IDX] == row.quad()[TripleIndex.OBJ_IDX]) { eligible[plane]++; }
			}
			assertTrue(matched[0] > 0 && matched[1] > 0 && eligible[0] > 0 && eligible[1] > 0,
					"both real pattern populations and eligible subpopulations must be sampled: " + fixture.trace);
			double explicitFraction = (double) eligible[0] / matched[0];
			double inferredFraction = (double) eligible[1] / matched[1];
			assertTrue(Math.abs(explicitFraction - inferredFraction) > 1.0e-9,
					"the sampled repeated-variable fractions must distinguish raw and eligible weights");
			assertNotNull(fixture.trace.pairedResult);
			assertTrue(fixture.trace.pairedResult.explicit().patternMassKnown());
			assertTrue(fixture.trace.pairedResult.inferred().patternMassKnown());
			assertEquals(rowsPerPlane, fixture.trace.pairedResult.explicit().patternMass());
			assertEquals(rowsPerPlane, fixture.trace.pairedResult.inferred().patternMass());
			assertTrue(fixture.trace.pairedResult.exactPageQuote() <= fixture.trace.pairedResult.exactPageAllowance());
			assertTrue(fixture.trace.examined <= fixture.trace.pairedResult.exactPageAllowance());
			assertTrue(fixture.trace.pairedResult.exactPageAllowance() <= budget);
			long eligibleCount = eligible[0] + eligible[1];
			long minimumEvidence = Math.min(33L, (long) fixture.trace.pairedResult.exactPageAllowance());
			if (budget == 64) {
				assertEquals(32D, fixture.trace.pairedResult.exactPageAllowance());
				assertTrue(eligibleCount < minimumEvidence, "the adaptive pass has insufficient eligible evidence");
				assertEquals(-1.0d, estimate.passRatio(), 0.0d);
				assertEquals(-1L, estimate.sampleSize());
			} else {
				assertTrue(eligibleCount >= minimumEvidence, "the positive case must satisfy actual evidence admission");
				assertEquals(explicitFraction / (explicitFraction + inferredFraction), estimate.passRatio(), 1.0e-12,
						"equal raw populations receive weights proportional to their sampled eligible fractions: matched="
								+ java.util.Arrays.toString(matched) + ", eligible=" + java.util.Arrays.toString(eligible)
								+ ", trace=" + fixture.trace);
				assertTrue(estimate.sampleSize() > 0 && estimate.sampleSize() <= eligibleCount);
			}
			assertTrue(fixture.trace.examined <= budget);
		}
	}

	private static long[] countPlane(Fixture fixture, ReadSession read, long predicate, long matchingObject,
			boolean explicit) throws IOException {
		long[] totals = new long[2];
		try (RecordIterator rows = fixture.store.getBackingStore().getTripleStore()
				.getTriples(read.txn, -1L, predicate, -1L, -1L, explicit)) {
			long[] row;
			while ((row = rows.next()) != null) {
				totals[0]++;
				if (row[TripleIndex.OBJ_IDX] == matchingObject) { totals[1]++; }
			}
		}
		return totals;
	}

